// Team PhASE logo: Latin Modern wordmark + phase mark (generated by media/brand/make_logo.py).

import { useApp } from '../../store/app';

export function TeamLogo({ height = 32, markOnly = false }: { height?: number; markOnly?: boolean }) {
  const theme = useApp((s) => s.theme);
  const file = markOnly ? 'team-phase-mark.svg' : `team-phase-${theme === 'light' ? 'light' : 'dark'}.svg`;
  return (
    <img
      src={`${import.meta.env.BASE_URL}brand/${file}`}
      alt="Team PhASE"
      height={height}
      style={{ height, width: 'auto', display: 'block' }}
      draggable={false}
    />
  );
}
